CREATE TABLE t3(a,b,c,d); CREATE INDEX t3i1 ON t3(a); CREATE INDEX t3i2 ON t3(a,b,c,d); CREATE INDEX t3i3 ON t3(d,b,c,a); CREATE TABLE t4(x,y,z); CREATE INDEX t4i1 ON t4(x); CREATE INDEX t4i2 ON t4(y); INSERT INTO t3 VALUES(1,2,3,4); INSERT INTO t3 VALUES(5,6,7,8); INSERT INTO t3 SELECT a+8,b+8,c+8,d+8 FROM t3; INSERT INTO t3 SELECT a+16,b+16,c+16,d+16 FROM t3; INSERT INTO t3 SELECT a+32,b+32,c+32,d+32 FROM t3; INSERT INTO t3 SELECT a+64,b+64,c+64,d+64 FROM t3; INSERT INTO t4 SELECT a,b,c FROM t3; ANALYZE; DROP INDEX t3i2;